import{_ as l,b as a,e as i,a7 as e}from"./chunks/framework.CFO60l-h.js";const b=JSON.parse('{"title":"推免要点","description":"国新系推免资格、综合评价、六级门槛与材料清单的结构化整理。","frontmatter":{"title":"推免要点","description":"国新系推免资格、综合评价、六级门槛与材料清单的结构化整理。","type":"baoyan-rules","tags":["保研","推免","资格"],"updated":"2026-11-07T00:00:00.000Z"},"headers":[],"relativePath":"baoyan/rules.md","filePath":"baoyan/rules.md","lastUpdated":null}'),r={name:"baoyan/rules.md"};function o(d,t,n,s,h,u){return a(),i("div",null,[...t[0]||(t[0]=[e('<h1 id="推免要点" tabindex="-1">推免要点 <a class="header-anchor" href="#推免要点" aria-label="Permalink to &quot;推免要点&quot;">​</a></h1><blockquote><p>以下为 2026 年分享会与公开信息整理，<strong>不是官方文件</strong>；资格线、比例、材料要求以当年学院/教务处通知为准。</p></blockquote><h2 id="一、两条线" tabindex="-1">一、两条线 <a class="header-anchor" href="#一、两条线" aria-label="Permalink to &quot;一、两条线&quot;">​</a></h2><ol><li><strong>本校推免资格</strong>：按学院综合评价排序，拿到名额。</li><li><strong>目标院校接收考核</strong>：夏令营/预推免/复试，拿到接收意向。</li></ol><p>只拿到一条都不算完成。</p><h2 id="二、综合评价" tabindex="-1">二、综合评价 <a class="header-anchor" href="#二、综合评价" aria-label="Permalink to &quot;二、综合评价&quot;">​</a></h2><ul><li><strong>学业成绩权重最高</strong>：绩点是重中之重。</li><li><strong>科研</strong>：求是学术、大创、创新杯、挑战杯、论文、课题组等。</li><li><strong>素质拓展</strong>：学生工作、志愿服务、竞赛、实践等。</li><li><strong>英语</strong>：本院国新方向六级 <strong>520</strong> 是硬门槛；外保看目标项目要求。</li></ul><blockquote><p>具体权重、加分细则每年可能调整；不要用往年比例硬套。</p></blockquote><h2 id="三、四条路径" tabindex="-1">三、四条路径 <a class="header-anchor" href="#三、四条路径" aria-label="Permalink to &quot;三、四条路径&quot;">​</a></h2><table tabindex="0"><thead><tr><th>路径</th><th>准备重点</th><th>风险</th></tr></thead><tbody><tr><td>国新（国际新闻传播）</td><td>模拟面试、个人辨识度、科研/素拓、英语</td><td>竞争加剧，需要提前演练</td></tr><tr><td>专硕</td><td>专业书通读 → 专题 → 记忆 → 面试</td><td>复习周期长，容易后期赶</td></tr><tr><td>学硕（本院）</td><td>早启动、学术潜质、研究经历</td><td>面试重思维纵深</td></tr><tr><td>外保</td><td>成绩、科研、专业背景、英语、论文</td><td>目标项目要求差异大</td></tr></tbody></table><h2 id="四、材料清单" tabindex="-1">四、材料清单 <a class="header-anchor" href="#四、材料清单" aria-label="Permalink to &quot;四、材料清单&quot;">​</a></h2><ul><li>[ ] 成绩单（盖章）</li><li>[ ] 排名证明</li><li>[ ] 英语成绩单（六级/雅思/托福）</li><li>[ ] 个人陈述/简历</li><li>[ ] 推荐信（如需要）</li><li>[ ] 科研/竞赛/实践证明</li><li>[ ] 论文/作品集（按方向）</li><li>[ ] 身份证/学生证复印件（按通知）</li></ul><h2 id="五、时间与流程" tabindex="-1">五、时间与流程 <a class="header-anchor" href="#五、时间与流程" aria-label="Permalink to &quot;五、时间与流程&quot;">​</a></h2><ol><li>学院发布推免通知/细则。</li><li>学生申请 + 材料提交。</li><li>资格审核/排名公示。</li><li>复试/面试（如有）。</li><li>推免系统填报/确认。</li></ol><h2 id="六、不要做" tabindex="-1">六、不要做 <a class="header-anchor" href="#六、不要做" aria-label="Permalink to &quot;六、不要做&quot;">​</a></h2><ul><li>不要伪造材料、虚报排名。</li><li>不要用往年模板替代当年要求。</li><li>不要同时承诺多个学校后违约；会影响学院声誉。</li><li>不要把“经验帖”当成官方文件。</li></ul><div class="danger custom-block"><p class="custom-block-title">以官方为准</p><p>推免资格、加分、排名、材料要求，全部以当年学院/教务处通知为准。本页只帮你整理思路。</p></div>',17)])])}const p=l(r,[["render",o]]);export{b as __pageData,p as default};
